  AND ((CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :FUNCTIONAL_AREA_UUID, ',%')) OR
		(CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(FUNCTIONAL_AREA_UUID, '') = '') OR
		(COALESCE(TENANT_UUID, '') = '' AND COALESCE(FUNCTIONAL_AREA_UUID, '') = ''))
UNION 
SELECT 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as label, 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as NAME, 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID as ID, 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID as value 
FROM 
  STEP_DEFINITION_TEMPLATE_VERBIAGE 
where 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID =:STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID